```typescript
// src/App.tsx
import React, { useEffect, useRef } from 'react';
import { Linking } from 'react-native';
import { handleOAuthRedirect } from './auth/oauthRedirectHandler';
import { navigationService } from './navigation/navigationService';

/**
 * Security rules applied:
 * - §4 Deep Links: single entry point for all incoming URLs; every URL
 *   passes through the same allowlist resolver.
 * - Handles both cold-start and warm-start deep links.
 */

export default function App() {
  const navigationRef = useRef(null);
  const handledInitialUrl = useRef(false);

  useEffect(() => {
    navigationService.setNavigationRef(navigationRef.current);

    // Cold start: check for initial URL
    Linking.getInitialURL().then((url) => {
      if (url && !handledInitialUrl.current) {
        handledInitialUrl.current = true;
        handleOAuthRedirect(url);
      }
    });

    // Warm start: listen for incoming URLs
    const subscription = Linking.addEventListener('url', ({ url }) => {
      handleOAuthRedirect(url);
    });

    return () => {
      subscription.remove();
    };
  }, []);

  // ... rest of app component
}
```

## Security Decisions Summary

- **§4 Deep Links**: Single resolver with exact hostname allowlist, https-only, typed/bounded parameter validation, state validation (session-bound, single-use), no identity/authority from URL.
- **§1 Storage**: Refresh credential and PKCE verifier in `react-native-keychain` only (iOS Keychain / Android Keystore), device-only accessibility, biometric invalidation on enrollment change.
- **§3 Binary Trust**: No client secret in bundle; code exchange via our backend gateway; PKCE S256 mandatory; Custom Tabs (not embedded WebView).
- **§4 Deep Links**: OAuth state is random, session-bound, single-use; cleared immediately after validation to prevent replay.
- **§1 Storage**: Access token in memory only; never persisted to any storage mechanism.
